"""Manuscript-ready v6.2 legends, rendered separately for image-only critique."""
from pathlib import Path
import pandas as pd

D=Path(__file__).resolve().parent/'out/v6/data'


def legends():
    def t(name):return pd.read_csv(D/(name+'.csv'),low_memory=False)
    z=t('z80_payload').query('eligible_dividing==True');e=t('capacity_edits');ev=t('evolved6502_capacity')
    a=t('allele_dial');w=a[a.culture_replicator]
    v=t('8086_validation').iloc[0];impact=t('impact').query("core=='C1'").iloc[0]
    claims=t('claims');comp=t('components');branch=t('branching');pe=t('parent_environment')
    s=t('capacity_serial');hap=t('capacity_haplotypes');lineage=hap.query("edit_id=='ldir32_v60' and direction=='forward'").iloc[0]
    refs=t('reference_traces')
    reference_counts=[]
    for key,name in [('pusher16','Pusher'),('ret16','Return R')]:
        b=branch.query("cohort=='Historical' and arm=='U' and gen==8 and key==@key").iloc[0]
        r=refs[refs.key==key].iloc[0]
        reference_counts.append(f"{name}: {int(b.ctrl_alive_n)}/{int(b.ctrl)} controls alive, {int(b.sites)}/{int(b.L)} retained sites, {int(r.entered_n)}/{int(r.encounters)} partner entries and {max(0,r.H_bits):.2f} bits inflow")
    reference_note='; '.join(reference_counts)+'.'
    branching_counts=[]
    for key,name in [('pusher16','Pusher'),('ret16','Return R'),('ldir32','Block-copy R'),('genome20_s6003','Transmitter')]:
        b=branch.query("cohort=='C1' and arm=='U' and gen==8 and key==@key").iloc[0]
        branching_counts.append(f"{name}: {int(b.ctrl_alive_n)}/{int(b.ctrl)} controls alive, {int(b.n_identifiable):,} identifiable alternatives x {int(b.reps)} starts, {int(b.sites)}/{int(b.L)} scored sites")
    branching_note='; '.join(branching_counts)+'.'
    missing=t('missing_trajectories');c1_missing=int((missing.cohort=='C1').sum())
    trajectory_note=('C1 and historical curves are medians across worlds at every archived sample. All 40 C1 raw logs were downloaded from algocell-atlas-runs using modal volume get only, and verified against the frozen dispatch spec, recorded completion markers, machine core/world/WGSL hashes and all endpoint measurements. No Modal function was invoked.' if not c1_missing else f'{c1_missing} C1 trajectory worlds could not be verified; historical curves remain and no invented C1 trajectory is drawn.')
    return {
1:f'''**Figure 1. Zilion makes reproduction an experiment.**

a, Reserved designer frame for the encounter contract. b, Reserved designer frame for the three abstract reproductive mechanisms. No illustrative result is inferred from either frame.

c, One historical illustrative world, seed 2002, with 20,000 cells and 16 bytes per cell. Teal is the fraction of cells with at least 12 of 16 bytes matching the contemporaneous modal tape; grey is the fraction of zero-valued bytes among 320,000 bytes. Modal match is a sequence-similarity neighbourhood, not a spatial-neighbour count or a median world history. The pusher16 and ret16 reference assays, partner entry and inflow measurements are moved to ed_v6_reference; those tapes are not asserted to descend from the illustrative world. The reference assays use generation-eight unmutated branching populations out of 64, thresholded positions out of tape length, instruction entry among 256 fresh-partner encounters, and offspring entropy in bits. {reference_note} Their archived traces are the G/L16/seed2001 first and final records.

d, Grey bars give the preserved fraction at each distinct validation level; vermilion gives the complementary loss of agreement. The architectural baseline contains {int(v.pass_arch):,} raw passes among {int(v.tests):,} 8088 hardware vectors, with {int(v.tests-v.pass_arch):,} expected divergences, zero unexpected architectural divergences, and queue timing outside the vector contract. The C1 audit preserves {int(impact.unaffected)}/{int(impact.decision_conditions)} ring-encounter conditions and {int(impact.assay_identical)}/{int(impact.assay_combinations)} isolated-assay cases; {int(impact.flagged)} conditions are flagged and {int(impact.assay_differences)} assay cases change. It preserves {int((claims.status=='stands').sum())}/{len(claims)} registered claim verdicts and {int((comp.comparison=='same').sum())}/{len(comp)} components. These rows have different counting units and no common replicate denominator. Instruction-vector agreement is not evidence of ecological replication. No 8086 ecology result is plotted; that population study awaits S2. Source tables: results/impact/outcome.csv, results/tier2/T2_CLAIMS.csv and T2_COMPONENTS.csv, and the generated 8086-architectural.json baseline.''',
2:f'''**Figure 2. Survival is not retention.**

a, Registered uniform-partner branching assays through generation eight. Black lines show surviving control populations divided by 64 starting control populations; vermilion shows surviving mutant populations divided by all starting mutant populations; teal shows marker-carrying populations divided by the same mutant starts, not by surviving populations. The historical measurements are open markers and the C1 corrected-core rerun is the solid line; they coincide exactly. Direct labels are shown once, in the first subplot. Each position has 32 tested alternatives and four independently founded populations per alternative. At generation eight: {branching_note} A population carries when at least half its members contain the mutant's centred five-byte window after cyclic alignment. Scored sites use the registered background-corrected criterion in at least half the tested alternatives. X1-2 was a completed experiment whose prediction failed, with zero scored sites. Sources: results/branching/branching_summary.csv and results/tier2/scored/Branching/branching_summary.csv; all counts are preserved in out/v6/data/branching.csv.

b, Historical serial-transfer maps at generation eight, for all 255 alternative bytes at every position and 16 serial lineages per alternative: 4,080 alternatives each for Pusher and Return R, 8,160 for Block-copy R, and 5,100 for Transmitter. Teal means at least one surviving lineage carries the introduced five-byte window; vermilion means survivors exist but none carries it; light grey means all lines are lost; dark grey denotes unchanged parental bytes, which were untested. Small brackets below the axes mark contiguous runs of fetched core positions. Any-carrier maps are distinct from thresholded site maps. Rare core-position carriers occur at block-copy R position 0 (16 alternatives) and transmitter positions 2 and 3 (6 and 50 alternatives). These counts are mutation types, not retained sites or independent worlds. All alternative and site counts remain in retention_maps.csv and retention_sites.csv, generated from results/serial_retention/sr_mutants.csv.gz and sr_sites.csv.

c, One exploratory ldir32 lineage with an introduced mutation at position 8, followed through two full 128-step encounters against zero partners. Grey dots give every write in executor order. The vermilion circle identifies overwrite at step 6. At step 128 the actual descendant becomes the focal parent and processor state resets. All 1,014 fetch/read/write events are archived in erasure_ordered.csv, with complete memory and ancestry states in erasure_states.csv. The original-marker ancestry trace, which falls from one byte to zero and stays zero during descendant reproduction, is moved to ed_v6_erasure.

d, Six L16 parents in six partner/reset environments. An unfilled tile with a grey cross denotes extinction of all unmutated controls; peach denotes measured zero retained sites; darker teal indicates more retained sites, normalized to the maximum in this panel. No number is printed in a tile. Exact control survival counts, denominators and retained-site counts are in data/ed_parent_environment.csv. Controls use 256 serial lineages; site scoring uses all 255 alternatives per position and 16 serial lines per alternative, with the background-corrected marker criterion in at least half of identifiable alternatives. Panels a and d have distinct parents, units and mutation panels. Soup samples supply partner backgrounds, not independent world replicates. Source: results/pe/pe_matrix.csv. No confidence interval is implied by a tile.''',
3:f'''**Figure 3. An inherited displacement controls payload.**

a, Clean frame reserved for the designer's abstract forward-copy geometry.

b, One identity line compares predicted free payload with measured positions. Light grey discs are exploratory Z80 population retention scores: {len(z):,} cells from {z.world.nunique()} worlds, with disc area exactly proportional to the number of cells at each coordinate; the area key shows 1, 100 and 2,000 cells. Population discs are drawn first, with smaller discs above larger ones. Filled teal circles are exact capacities of {len(e)} registered C1 edited Z80 descendants from {e.key.nunique()} archived parents; filled teal triangles are {len(ev)} eligible evolved 6502 copier roles from {ev.world.nunique()} registered C2 worlds. Small open squares are sampled carried-position counts for 296 qualifying constructed 6502 cases. These three series are dodged along the identity diagonal by display-only equal x/y offsets (C1 -1, C2 +2, controls +1 positions), preserving exact agreements on y = x; population scores, including the gate deficit at (4, 0), remain at their true coordinates. A small unfilled grey ring highlights the gate deficit without changing its count-scaled disc area. Thus the ordinate distinguishes exact capacity from sampled retention scores/counts; all use positions. Constructed carriage requires the original byte at the aligned offspring position in all 64 encounters for each of three payload bodies (192 encounters per case); it is not an exhaustive capacity measurement. The open diamond in the symbol key is reserved for evolved 8086 copiers after S2; no 8086 point is plotted. Coincident coordinates retain their exact values and multiplicities in law_population.csv, law_z80_c1.csv, law_6502_c2.csv and law_6502_controls.csv. The population screen excludes four source cells failing divisibility/range conditions; {int((z.fetched_extra>0).sum())} eligible cells have additional scored fetched sites, and one cell has a gate-related score deficit of four positions, not a demonstrated zero capacity. The world/prediction mean residual, low-capacity magnification and reciprocal intervention scatter are moved to ed_v6_law. Sources: results/offset/offset_cells.csv, results/crystal/cells.csv and cell_exceptions.csv, results/capacity/, results/evolved6502/ and results/census6502/table_closers_law.csv. Motif/divisibility screening alone does not certify every theorem prerequisite.

c, Exact registered C1 ldir32 lineage 0 at generation eight, using the same 32 offspring positions for two intervention arms. At displacement 4, core positions 0–3 are grey and every payload position 4–31 is erased (vermilion). Editing byte 0 from hexadecimal 04 to 60 gives displacement 32; the edit is inherited, the core stays grey and positions 4–31 transmit (teal). States are computed from the archived causal-source indices, not from superficial byte equality. The lower generation-eight offspring is {lineage.offspring}. The corresponding source indices are {lineage.sources}. The two strips are parallel intervention lineages, not consecutive observations of an edit arising spontaneously. The registered experiment follows each of {len(e)} edits in 16 lineages for eight generations in both forward and reciprocal directions; {int(s.lineages.sum()):,} serial records are repeated observations, not independent edits. Each exact free position passes all 255 alternatives against all 17 frozen partners. The plotted 64 states and edited bytes come from results/capacity/edit_eligibility.csv and serial.csv.gz, in data/lineage_strips.csv. Full exact single, joint and beyond-prefix challenges are moved to ed_v6_joint_table.pdf and data/ed_joint_challenges.csv. Joint challenges sample 64 assignments per edit or eligible copier, include zero-payload controls, and check full offspring plus causal ancestry. Beyond-prefix success denotes erasure. Constructed eligibility excludes 5,848 of 6,144 screened cases; those exclusions are not joint-challenge failures. Controlled joint tests of inadequate coverage or altered phase remain outstanding; no 8086 joint result is inferred.

d, Exploratory byte sweep from results/crystal/alleles_ldir32.csv, all 256 values tested at byte 0 of ldir32 (L = 32, four-byte core). The 16 × 16 map covers hexadecimal 00–FF: rows give the high nibble and columns the low nibble, with 00 at the upper left. Very light grey squares are the {len(a)-len(w)} non-working values; white squares with thin teal outlines are the {len(w)-int(w.prop8_eligible.sum())} working values outside the theorem's recorded conditions. Teal-filled squares are the {int(w.prop8_eligible.sum())} working eligible values, shaded continuously by predicted free payload d − 4 from 0 to L − 4 = 28 positions. Eligibility requires the C1 forward-copy/protected-prefix conditions, 4 ≤ d ≤ L, d dividing L, and sufficient copy coverage; the exploratory prop8_eligible flag records the sampled first-instruction check of those prerequisites. Only these values have a defined predicted_payload; outside-condition values have no payload prediction and are not assigned nominal arithmetic in the map. Here d is the effective displacement modulo the 64-byte encounter ring. Black outlines identify the original value 04 (d = 4, predicted payload 0) and edited value 60 (d = 32, predicted payload 28). Working means two-generation normalized culture gain ≥ 0.3 against fixed panels of 16 uniform partners. This exploratory sweep is separate from registered C1 exact serial capacities in b and c and does not itself certify partner-universal or multigeneration inheritance.''',
4:f'''**Figure 4. Environments sort reproductive designs.**

a, Mutation-on L32 competitions. The ordinate is transmitter share T/(R+T), where R is a regenerator and T a transmitter; it is distinct from core abundance divided by all 20,000 cells. Teal is benign tar and purple is lethal tar. C1 corrected-core trajectories are solid-opacity lines and historical trajectories are faint lines in the same hues. Starting mixtures use solid lines for equal R:T shares (10 worlds per chemistry/cohort), dashed for R introduced at 1% into T (five), and dotted for T introduced at 1% into R (five). {trajectory_note} Core-abundance trajectories are moved to ed_v6_competition. Sources: historical offset JSONLs and tier2/E/ and tier2/E-L32L/ logs; the local endpoint tables are results/offset/offset_switch.csv and results/tier2/scored/E/offset_switch.csv. The download audit and all generated-source hashes accompany the data.

b, World-level final T share at 300,000 steps. Historical worlds have open markers and C1 worlds filled markers; hue retains chemistry. Circles, squares and triangles denote equal-start, R-in-T and T-in-R worlds. Each chemistry/cohort has 20 registered worlds; one C1 benign core-loss world has an undefined T ratio and is omitted here, leaving 19 defined points in that group. Its measured zeros remain in the ED abundance and tail plots. Small horizontal offsets prevent collisions and carry no quantitative meaning. Tail diversity is nested within world, not an additional replicate. The complete 80-world endpoint table remains in competition_endpoints.csv, with deterministic plotting offsets in endpoint_positions.csv. Absolute core abundance and distinct transmitter tails are moved to ed_v6_competition.

c, Lethality probability versus open-first and transmitter-majority world counts, each out of all ten registered worlds per setting. Historical measurements use open grey markers with a dashed line; C1 uses filled black markers with a solid line. Probability settings are categorical and equally spaced; slopes do not express change per unit probability. Open-first is a first detected heritable top-three tape occupying at least 0.5% of the population and fetching partner instructions in at least 8 of 16 traced encounters. Transmitter majority is more than half of sampled heritable cells. Worlds without detection remain in both denominators. Confinement means a heritable top-three tape at that abundance fetches no partner instruction in all 16 encounters. Its Kaplan–Meier median uses all ten worlds and censors nondetections at the 300,000-step horizon; this timing is moved to ed_v6_confinement. DZ1 requires at least 8/10 open-first at p=0, at most 2/10 at p=1 and a falling rank trend with one-sided P<0.05. DZ2 requires at most one downward reversal across KM medians and positive Spearman correlation with permutation P<0.05; historical timing has two reversals and fails, C1 one and passes. DZ3 requires at most 3/10 transmitter-majority at p=0, at least 7/10 at p=1 and a positive share trend with permutation P<0.05; historical 6/10 at p=1 fails, C1 8/10 passes. The C1 timing drop from p=.3 to 1 remains in ED. Registration verdicts are legend context, not plotted observations. Sources: results/dial/dial_worlds.csv, results/tier2/scored/DZ/dial_worlds.csv, T2_DZ.csv and T2_COMPONENTS.csv. No mechanistic equilibrium curve is fitted.'''
    }


def extended_legends():
    return {
        'ed_v6_reference':'''**Extended Data. Reference assays retain distinct units.**

a, Historical generation-eight Pusher and Return R control populations alive (grey), and marker-carrying mutant populations (teal), each divided by its starting populations. These are separate reference assays, not descendants of the Figure 1c illustrative world. b, Fraction of 256 fresh-partner encounters that fetch a partner instruction. c, Offspring entropy across the same partners, in bits. See Figure 1c legend for exact counts and definitions. Sources: generated branching.csv and reference_traces.csv.''',
        'ed_v6_erasure':'''**Extended Data. Original-marker ancestry disappears during ordered copying.**

a, Ring bytes causally descended from the introduced position-8 mutation in the Figure 2c exploratory ldir32 lineage. The original marker disappears at step 6 and remains absent after the actual descendant starts a second encounter at step 128. Both full 128-step encounters are archived; processor state resets between them. Source: erasure_ordered.csv. This is an ancestry count, not a measure of surviving mutant populations.''',
        'ed_v6_law':'''**Extended Data. Residuals and reciprocal interventions support the payload analysis.**

a, Z80 world/prediction mean sampled-score residual in positions. Cells are averaged within each world/prediction cluster; no interval is implied. The one gate-deficit cell is four positions below prediction; its five-cell cluster has mean residual -0.8. b, Low-capacity magnification of Figure 3b, with exact coincident coordinates. Grey open circles are population scores, teal circles C1 descendant capacities, teal triangles evolved C2 6502 capacities and open black squares constructed carriage counts. Marker sizes here identify layers, not multiplicity. c, Registered Z80 C1 exact capacities, forward filled teal circles and reciprocal open grey squares; a single identity line. Distinct zero-capacity edits remain separate in the tables even when coordinates coincide. Sources: z80_worlds.csv, law_*.csv, capacity_edits.csv and capacity_direct.csv. See Figure 3 legend for scoring and exhaustive capacity definitions.''',
        'ed_v6_joint_table':'''**Extended Data. Exact joint and boundary challenges are retained in a table.**

a, Counts of exact successes and intervention cases for registered Z80 C1 (both directions pooled) and evolved 6502 C2. Every intervention must pass all 17 frozen partners. All-value single challenges test every alternative; joint assignments sample 64 assignments per edit/copier and include zero-payload controls; beyond-prefix success means erasure into protected-source descendants. These are repeated intervention cases, not independent biological replicates. Z80 totals: 221,850 single, 12,928 joint and 832,830 erased cases. 6502 totals: 19,380 single, 2,688 joint and 69,360 erased cases. All succeed. The distinct exploratory constructed eligibility screen has 296 qualifying of 6,144 cases; 5,848 exclusions are not joint-test failures. Controlled joint tests of insufficient forward coverage or altered phase are absent from the existing archive. Sources: ed_joint_challenges.csv and constructed6502.csv.''',
        'ed_v6_competition':'''**Extended Data. Core abundance and tail diversity preserve every competition world.**

a, Final core-bearing abundance among 20,000 cells at 300,000 steps. b, Distinct transmitter tails within each world at the same endpoint. Open markers are historical; filled markers are C1. Teal denotes benign and purple lethal tar; circles, squares and triangles are equal-start, R-in-T and T-in-R worlds. There are 20 worlds in each chemistry/cohort group. Deterministic horizontal offsets avoid collisions and do not encode a measured variable. The C1 benign world with an undefined T ratio remains here with measured zero abundance and zero tail diversity. Tail counts are nested within worlds. c, Median core-bearing fraction against step; C1 is solid-opacity and historical faint. Solid lines denote equal-start worlds, dashed lines R introduced at 1% into T, and dotted lines T introduced at 1% into R. Sources: competition_endpoints.csv, endpoint_positions.csv and competition_medians.csv, generated from all endpoint tables and verified raw trajectories.''',
        'ed_v6_confinement':'''**Extended Data. Confinement timing remains a separate ecological measure.**

a, Kaplan-Meier median elapsed steps from soup initialization to first confinement, across all ten worlds at each probability. Confinement requires a detected heritable top-three tape at least 0.5% of population to fetch no partner instruction in all 16 traces. Nondetections are censored at 300,000 steps. Historical open grey markers have a dashed line; C1 filled black markers a solid line. The tested probability levels are categorical and equally spaced. The C1 p=.3 to p=1 downward timing reversal is retained; two historical reversals and one C1 reversal determine the differing DZ2 component verdicts, as defined in Figure 4c legend. Source: lethality_summary.csv and dial_worlds.csv.'''
    }
